import React, { useState } from 'react';
import LoginScreen from './components/auth/LoginScreen';
import AppLayout from './components/layout/AppLayout';
import Admin5Dashboard from './pages/admin5/Admin5Dashboard';

function App() {
  const [userRole, setUserRole] = useState(null);
  const [currentPage, setCurrentPage] = useState('dashboard');

  const loginAs = (role) => {
    setUserRole(role);
    setCurrentPage('dashboard');
  };

  const logout = () => {
    setUserRole(null);
  };

  const navigate = (page) => {
    setCurrentPage(page);
  };

  const renderPage = () => {
    switch (currentPage) {
      case 'dashboard':
        if (userRole === 'admin5') {
          return <Admin5Dashboard onNavigate={navigate} />;
        }
        return <h1>Dashboard para {userRole}</h1>;
      default:
        return <h1>Página: {currentPage}</h1>;
    }
  };

  if (!userRole) {
    return <LoginScreen loginAs={loginAs} />;
  }

  return (
    <AppLayout onNavigate={navigate} onLogout={logout} activePage={currentPage}>
      {renderPage()}
    </AppLayout>
  );
}

export default App;
